package hikversion;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.InputStream;
import java.util.Base64;

/**
 * @author:jinyandong
 * @description:测试生成Bmp文件
 * @Date:2023/11/13
 */
public class TestBmpCopySansi {
    public static void main(String args[]) throws Exception {
        // 设备端返回的Bse64加密的字符串信息
        String str = "";
        uploadFileToLocal(str);
    }

    /**
     * 根据设备端返回的数据转换成的字符串生成bmp文件
     *
     * @param str：设备端返回的base64加密的字节数组
     * @throws Exception
     */
    public static void uploadFileToLocal(String str) throws Exception {
        byte[] decode = Base64.getDecoder().decode(str);
        InputStream inputStream = new ByteArrayInputStream(decode);
        try {
            BufferedImage image = ImageIO.read(inputStream);
            // 文件生成路径
            File output = new File("D:\\sansib001.bmp");
            if (output.exists()) {
                output.delete();
            }
            ImageIO.write(image, "bmp", output);
        } catch (Exception e) {
            System.out.println("error");
        } finally {
            inputStream.close();
        }
    }

}
